# Life machine asset repaint and geometry pass; preserves blockstate semantics.
Add-Type -AssemblyName System.Drawing
$root=Join-Path $PSScriptRoot 'common\src\main\resources\assets\akaishi'
$tex=Join-Path $root 'textures\block'; $models=Join-Path $root 'models\block'; $prev=Join-Path $PSScriptRoot 'gui_layouts\life_rework_preview.png'
function Paint($n,$accent,$kind){$b=New-Object Drawing.Bitmap(64,64);$g=[Drawing.Graphics]::FromImage($b);$g.Clear([Drawing.Color]::FromArgb(25,31,38));$p=New-Object Drawing.SolidBrush([Drawing.ColorTranslator]::FromHtml('#53616A'));$g.FillRectangle($p,3,3,58,58);$p.Color=[Drawing.ColorTranslator]::FromHtml('#18232B');$g.FillRectangle($p,8,8,48,48);$p.Color=[Drawing.ColorTranslator]::FromHtml($accent);if($kind -eq 'scanner'){$g.FillRectangle($p,14,12,36,5);$g.FillRectangle($p,14,47,36,5);$g.FillRectangle($p,14,12,5,40);$g.FillRectangle($p,45,12,5,40)}elseif($kind -eq 'vault'){$g.FillRectangle($p,16,14,32,36);$p.Color=[Drawing.ColorTranslator]::FromHtml('#B8E8D0');$g.FillRectangle($p,22,20,20,3);$g.FillRectangle($p,22,27,20,3);$g.FillRectangle($p,22,34,20,3)}else{$g.FillRectangle($p,14,14,36,36);$p.Color=[Drawing.ColorTranslator]::FromHtml('#D7FFE4');$g.FillRectangle($p,25,22,14,20);$g.FillRectangle($p,20,29,24,5)}$p.Dispose();$g.Dispose();$b.Save((Join-Path $tex ($n+'.png')),[Drawing.Imaging.ImageFormat]::Png);$b.Dispose()}
$set=@(@('akaishi_gene_analyzer','#53D6C2','analyzer'),@('akaishi_gene_manager','#C88BFF','manager'),@('akaishi_body_scanner','#66B9FF','scanner'),@('akaishi_organ_vault','#E9A45B','vault'),@('akaishi_sample_vault','#67D99B','vault'))
foreach($s in $set){$n=$s[0];Paint ($n+'_top') $s[1] $s[2];Paint ($n+'_side') $s[1] $s[2];Paint ($n+'_bottom') '#202A31' 'bottom';$e=@{from=@(0,0,0);to=@(16,16,16);faces=@{down=@{texture='#bottom'};up=@{texture='#top'};north=@{texture='#side'};south=@{texture='#side'};west=@{texture='#side'};east=@{texture='#side'}}};$e2=@{from=@(2,2,2);to=@(14,14,14);faces=@{up=@{texture='#top'};north=@{texture='#side'};south=@{texture='#side'};west=@{texture='#side'};east=@{texture='#side'}}};$m=@{parent='minecraft:block/block';textures=@{bottom="akaishi:block/${n}_bottom";top="akaishi:block/${n}_top";side="akaishi:block/${n}_side"};elements=@($e,$e2)};[IO.File]::WriteAllText((Join-Path $models ($n+'.json')),(ConvertTo-Json $m -Depth 12),(New-Object Text.UTF8Encoding($false)))}
$sheet=New-Object Drawing.Bitmap(320,80);$g=[Drawing.Graphics]::FromImage($sheet);$g.Clear([Drawing.Color]::FromArgb(12,15,19));for($i=0;$i -lt $set.Count;$i++){ $path=Join-Path $tex ($set[$i][0]+'_top.png');$im=[Drawing.Image]::FromFile($path);$g.DrawImage($im,($i*64),8);$im.Dispose() };$g.Dispose();$sheet.Save($prev,[Drawing.Imaging.ImageFormat]::Png);$sheet.Dispose();Write-Output "painted $($set.Count) life machines; preview $prev"